C_LAT, C_LON = 29.93480, 52.89050
M_LAT = 1.0 / 110860.0
M_LON = 1.0 / (111320.0 * math.cos(math.radians(C_LAT)))


def L(x, y):
    return (round(C_LAT + y * M_LAT, 6), round(C_LON + x * M_LON, 6))


